"""Pipeline schedule simulator: bubbles and activation memory per device (lesson 09.2).

A pipeline schedule is, for every device, an ordered list of operations on micro-batches:

* ``F``  forward of one chunk (a stage's layers) for one micro-batch;
* ``B``  full backward of one chunk (input gradient and weight gradient together, time ``B + W``);
* ``Bz`` backward for the *input* only (time ``B``); its weight gradient becomes a separate ``W`` op that
  can run later (the zero-bubble split, Qi et al., arXiv 2401.10241);
* ``W``  weight-gradient computation of a chunk whose ``Bz`` already ran (time ``W``);
* ``FB`` a forward of one chunk overlapped with a full backward of another chunk on the same device
  (DualPipe's "F&B", time ``fb``; by default ``F + B + W``, i.e. no compute gain — the gain in DeepSeek-V3
  is that all-to-all communication hides under it, which this compute-only model does not include).

Dependencies: a chunk's forward needs the previous stage's forward of the same micro-batch; its backward
needs its own forward and the next stage's backward; ``W`` needs its ``Bz``. Each device runs its ops in
list order, each as soon as its inputs are ready (plus ``latency`` for a transfer between devices). The
result is exact for the model — the longest path through the dependency graph — so it is a test oracle for
the closed-form bubble formulas:

    GPipe / 1F1B, p stages, m micro-batches:  idle per device = (p-1)(F+B+W);  ratio (p-1)/(m+p-1)
    interleaved 1F1B with v chunks per device: idle per device = (p-1)(F+B+W)/v   (Narayanan et al. 2021)
    DualPipe / DualPipeV (DualPipe README):    bubble (PP/2-1)(F&B + B_full - 3W)

The zero-bubble schedule here (``zb1p``) is 1F1B with every backward split into ``Bz`` and a deferred ``W``;
a device runs a pending ``W`` whenever its next op is not ready, and before a forward that would hold more
than ``p`` micro-batches of activations (1F1B's peak) — the ZB-H1 idea with greedily placed W ops. DualPipe and DualPipeV follow the step structure of
``dualpipe/dualpipe.py`` and ``dualpipe/dualpipev.py`` in github.com/deepseek-ai/DualPipe (main branch,
read 2026-10-04): the same eight phases, the same op counts per rank.

Activation memory is counted in units of "one chunk of L/PP layers for one micro-batch", allocated when a
forward starts and freed when the chunk's last backward op (``B``, or ``W`` after a ``Bz``) ends.
"""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field


@dataclass
class Op:
    kind: str                       # "F" | "B" | "Bz" | "W" | "FB"
    f: tuple | None = None          # (path, mb, stage) of the forward part
    b: tuple | None = None          # (path, mb, stage) of the backward part (B, Bz, W, FB)
    defer: bool = False             # Bz only: its W is left to the simulator (fills idle time)


@dataclass
class Schedule:
    name: str
    devices: int
    paths: list                     # paths[p][stage] = device
    ops: list                       # ops[device] = [Op, ...]
    act: dict = field(default_factory=dict)       # (path, stage) -> activation units per micro-batch
    greedy_w: bool = False          # zb1p: W ops are generated by the simulator
    w_cap: list | None = None       # live-activation cap per device for greedy W

    def n_micro(self, path: int) -> int:
        return len({op.f[1] for ops in self.ops for op in ops if op.f and op.f[0] == path})


# ---- generators -------------------------------------------------------------------------------------

def gpipe(p: int, m: int) -> Schedule:
    """All forwards, then all backwards (GPipe, arXiv 1811.06965)."""
    ops = [[Op("F", f=(0, i, s)) for i in range(m)] + [Op("B", b=(0, i, s)) for i in range(m)] for s in range(p)]
    return Schedule("GPipe", p, [list(range(p))], ops, {(0, s): 1.0 for s in range(p)})


def one_f_one_b_order(p: int, s: int, m: int) -> list[tuple[str, int]]:
    """1F1B op order on stage ``s``: ``p-s-1`` warm-up forwards, then forward/backward pairs, then backwards."""
    warm = min(p - s - 1, m)
    out = [("F", i) for i in range(warm)]
    for i in range(m - warm):
        out += [("F", warm + i), ("B", i)]
    out += [("B", i) for i in range(m - warm, m)]
    return out


def one_f_one_b(p: int, m: int) -> Schedule:
    """1F1B (PipeDream-Flush, arXiv 1806.03377; Megatron-LM arXiv 2104.04473)."""
    ops = [[Op("F", f=(0, i, s)) if kind == "F" else Op("B", b=(0, i, s)) for kind, i in one_f_one_b_order(p, s, m)]
           for s in range(p)]
    return Schedule("1F1B", p, [list(range(p))], ops, {(0, s): 1.0 for s in range(p)})


def zb1p(p: int, m: int) -> Schedule:
    """Zero-bubble 1F1B in the spirit of ZB-H1 (arXiv 2401.10241): 1F1B order with every backward split.

    Every ``Bz`` (input gradient) runs as soon as it can, so the backward chain between stages carries only
    ``B``, not ``B + W``. Its ``W`` is deferred: a device runs a pending ``W`` whenever its next op is not ready
    yet, or before a forward that would hold more than ``p`` micro-batches of activations — the peak of 1F1B's
    first stage, so no device needs more memory than 1F1B's worst one. The placement of the W ops is greedy,
    not the paper's hand-made one; the simulator reproduces the ``(p-1)(F + B_full - 2W)`` bubble of the
    DualPipe README for the cases in the tests.
    """
    ops = [[Op("F", f=(0, i, s)) if kind == "F" else Op("Bz", b=(0, i, s), defer=True)
            for kind, i in one_f_one_b_order(p, s, m)] for s in range(p)]
    return Schedule("ZB-1P", p, [list(range(p))], ops, {(0, s): 1.0 for s in range(p)}, greedy_w=True,
                    w_cap=[p] * p)


def interleaved(p: int, v: int, m: int) -> Schedule:
    """Interleaved 1F1B (Megatron-LM, arXiv 2104.04473 section 2.2): device s holds chunks s, s+p, ..., s+(v-1)p.

    Micro-batches go through the chunks in groups of ``p``; needs ``m % p == 0``. Warm-up forwards on device s:
    ``(p-s-1)·2 + (v-1)·p``.
    """
    if m % p:
        raise ValueError("interleaved 1F1B needs m to be a multiple of p")
    total = m * v

    def fwd(k):
        grp, within = divmod(k, p * v)
        return within // p, grp * p + within % p          # (chunk, mb)

    def bwd(k):
        grp, within = divmod(k, p * v)
        return v - 1 - within // p, grp * p + within % p

    ops = []
    for s in range(p):
        warm = min((p - s - 1) * 2 + (v - 1) * p, total)
        row = []
        for k in range(warm):
            c, i = fwd(k)
            row.append(Op("F", f=(0, i, c * p + s)))
        for j in range(total - warm):
            c, i = fwd(warm + j)
            row.append(Op("F", f=(0, i, c * p + s)))
            c, i = bwd(j)
            row.append(Op("B", b=(0, i, c * p + s)))
        for j in range(total - warm, total):
            c, i = bwd(j)
            row.append(Op("B", b=(0, i, c * p + s)))
        ops.append(row)
    path = [k % p for k in range(p * v)]
    return Schedule(f"Interleaved 1F1B (v={v})", p, [path], ops, {(0, k): 1.0 / v for k in range(p * v)})


class _DualBuilder:
    """Turns the DualPipe step structure into op lists. ``phase_of[rank][ph] = (path, stage)``."""

    def __init__(self, phase_of):
        self.phase_of = phase_of
        self.ops = []
        self.fc, self.bc, self.wq = [0, 0], [0, 0], deque()

    def key(self, ph, count):
        path, stage = self.phase_of[ph]
        return (path, count[ph], stage)

    def F(self, ph):
        k = self.key(ph, self.fc)
        self.fc[ph] += 1
        self.ops.append(Op("F", f=k))

    def B(self, ph, zb=False):
        k = self.key(ph, self.bc)
        self.bc[ph] += 1
        if zb:
            self.wq.append(k)
        self.ops.append(Op("Bz" if zb else "B", b=k))

    def W(self):
        self.ops.append(Op("W", b=self.wq.popleft()))

    def FB(self, ph_f, ph_b):
        kf = self.key(ph_f, self.fc)
        self.fc[ph_f] += 1
        kb = self.key(ph_b, self.bc)
        self.bc[ph_b] += 1
        self.ops.append(Op("FB", f=kf, b=kb))


def _dual_steps(bld: _DualBuilder, n_half: int, half_rank: int, chunks_per_phase: int, middle: bool):
    """The eight steps shared by dualpipe.py and dualpipev.py (with their rank arithmetic)."""
    for _ in range((n_half - half_rank - 1) * 2):                      # step 1: nF0
        bld.F(0)
    for _ in range(half_rank + 1):                                     # step 2: nF0F1
        bld.F(0)
        bld.F(1)
    for _ in range(n_half - half_rank - 1):                            # step 3: nB1W1F1 (zero bubble)
        bld.B(1, zb=True)
        bld.W()
        bld.F(1)
    step_4 = chunks_per_phase - 2 * n_half + half_rank + 1             # step 4: nF0B1F1B0 (main)
    for i in range(step_4):
        if i == 0 and middle:
            bld.F(0)
            bld.B(1)
        else:
            bld.FB(0, 1)
        bld.FB(1, 0)
    for _ in range(n_half - half_rank - 1):                            # step 5: nB1F1B0
        bld.B(1)
        bld.FB(1, 0)
    step_6 = half_rank + 1                                             # step 6: nB1B0
    zb = False
    for i in range(step_6):
        if i == step_6 // 2 and half_rank % 2 == 1:
            zb = True
        bld.B(1, zb=zb)
        if i == step_6 // 2 and half_rank % 2 == 0:
            zb = True
        bld.B(0, zb=zb)
    for _ in range(n_half - half_rank - 1):                            # step 7: nWB0
        bld.W()
        bld.B(0, zb=True)
    for _ in range(half_rank + 1):                                     # step 8: nW
        bld.W()
    assert not bld.wq, "every deferred weight gradient must be consumed"


def dualpipev(devices: int, m: int) -> Schedule:
    """DualPipeV: ``2·devices`` stages in a V (device d holds stages d and 2·devices-1-d); needs m >= 2·devices."""
    R = devices
    if m < 2 * R:
        raise ValueError("DualPipeV needs at least 2 x devices micro-batches")
    path = [k if k < R else 2 * R - 1 - k for k in range(2 * R)]
    ops = []
    for r in range(R):
        bld = _DualBuilder({0: (0, r), 1: (0, 2 * R - 1 - r)})
        _dual_steps(bld, R, r, m, middle=(r == R - 1))
        ops.append(bld.ops)
    return Schedule("DualPipeV", R, [path], ops, {(0, k): 1.0 for k in range(2 * R)})


def dualpipe(devices: int, m: int) -> Schedule:
    """DualPipe: two pipelines in opposite directions over the same ``devices`` (even), m/2 micro-batches each."""
    R = devices
    if R % 2 or m % 2 or m < 2 * R:
        raise ValueError("DualPipe needs an even number of devices, even m and m >= 2 x devices")
    paths = [list(range(R)), list(range(R - 1, -1, -1))]
    ops = []
    for r in range(R):
        if r < R // 2:
            phases = {0: (0, r), 1: (1, R - 1 - r)}
        else:
            phases = {0: (1, R - 1 - r), 1: (0, r)}
        bld = _DualBuilder(phases)
        half_rank = min(r, R - 1 - r)
        _dual_steps(bld, R // 2, half_rank, m // 2, middle=(half_rank == R // 2 - 1))
        ops.append(bld.ops)
    act = {(p, s): 1.0 for p in range(2) for s in range(R)}
    return Schedule("DualPipe", R, paths, ops, act)


# ---- simulation -------------------------------------------------------------------------------------

@dataclass
class Times:
    F: float = 1.0
    B: float = 1.0                  # input-gradient part of the backward
    W: float = 1.0                  # weight-gradient part
    fb: float | None = None         # overlapped forward+backward (default F + B + W)
    latency: float = 0.0            # transfer time between devices

    @property
    def B_full(self) -> float:
        return self.B + self.W


def simulate(sch: Schedule, t: Times = Times(), scale: dict | None = None) -> dict:
    """Run the schedule. Returns makespan, per-device busy/idle time, bubble ratio, peak activations.

    ``scale[(path, stage)]`` multiplies every op duration of that chunk (interleaved chunks are 1/v of a stage).
    """
    scale = scale or {k: v for k, v in sch.act.items()}
    end: dict = {}
    dev_of = lambda key: sch.paths[key[0]][key[2]]                                  # noqa: E731
    nst = [len(p) for p in sch.paths]

    def deps(op):
        out = []
        if op.f is not None:
            path, mb, k = op.f
            if k > 0:
                out.append(("F", path, mb, k - 1))
        if op.b is not None and op.kind in ("B", "Bz", "FB"):
            path, mb, k = op.b
            out.append(("F", path, mb, k))
            if k < nst[path] - 1:
                out.append(("B", path, mb, k + 1))
        if op.kind == "W":
            out.append(("B", *op.b))
        return out

    def dur(op):
        if op.kind == "F":
            return t.F * scale[(op.f[0], op.f[2])]
        if op.kind == "B":
            return t.B_full * scale[(op.b[0], op.b[2])]
        if op.kind == "Bz":
            return t.B * scale[(op.b[0], op.b[2])]
        if op.kind == "W":
            return t.W * scale[(op.b[0], op.b[2])]
        fb = t.fb if t.fb is not None else (t.F + t.B_full)
        return fb * 0.5 * (scale[(op.f[0], op.f[2])] + scale[(op.b[0], op.b[2])])

    def ready_time(op, d):
        r = 0.0
        for dep in deps(op):
            if dep not in end:
                return None
            lat = t.latency if dev_of(dep[1:]) != d and dep[0] != "W" else 0.0
            r = max(r, end[dep] + lat)
        return r

    D = sch.devices
    idx, free = [0] * D, [0.0] * D
    busy = [0.0] * D
    events = [[] for _ in range(D)]            # (time, +units/-units)
    pending_w = [deque() for _ in range(D)]
    live = [0.0] * D
    timeline = [[] for _ in range(D)]
    total_ops = sum(len(o) for o in sch.ops)
    done = 0

    def run(d, op, start):
        nonlocal done
        e = start + dur(op)
        free[d] = e
        busy[d] += e - start
        timeline[d].append((op.kind, op.f, op.b, start, e))
        if op.f is not None:
            end[("F", *op.f)] = e
            u = sch.act[(op.f[0], op.f[2])]
            events[d].append((start, u))
            live[d] += u
        if op.b is not None and op.kind in ("B", "Bz", "FB"):
            end[("B", *op.b)] = e
        if op.kind in ("B", "FB") or op.kind == "W":
            u = sch.act[(op.b[0], op.b[2])]
            events[d].append((e, -u))
            live[d] -= u
        if op.kind == "Bz" and op.defer:
            pending_w[d].append(op.b)

    while done < total_ops or any(pending_w):
        progress = False
        for d in sorted(range(D), key=lambda x: free[x]):
            if idx[d] >= len(sch.ops[d]):
                if pending_w[d]:                       # drain deferred weight gradients at the end
                    run(d, Op("W", b=pending_w[d].popleft()), free[d])
                    progress = True
                continue
            op = sch.ops[d][idx[d]]
            rt = ready_time(op, d)
            if rt is None:
                continue
            if sch.greedy_w and pending_w[d]:
                over_cap = op.kind == "F" and live[d] + 1e-9 >= sch.w_cap[d]
                if over_cap or rt > free[d]:          # fill the wait (or make room) with a deferred W
                    run(d, Op("W", b=pending_w[d].popleft()), free[d])
                    progress = True
                    continue
            run(d, op, max(free[d], rt))
            idx[d] += 1
            done += 1
            progress = True
        if not progress and sch.greedy_w:
            # every device waits on an op not simulated yet: the earliest-free device with a deferred W runs it
            cand = [d for d in range(D) if pending_w[d]]
            if cand:
                d = min(cand, key=lambda x: free[x])
                run(d, Op("W", b=pending_w[d].popleft()), free[d])
                progress = True
        if not progress:
            raise RuntimeError(f"{sch.name}: deadlock (an op waits for one that never runs)")

    makespan = max(free)
    peak = []
    for d in range(D):
        cur = best = 0.0
        for _, u in sorted(events[d], key=lambda x: (x[0], x[1])):   # frees before allocations at equal times
            cur += u
            best = max(best, cur)
        peak.append(best)
    idle = [makespan - b for b in busy]
    return {"name": sch.name, "devices": D, "makespan": makespan, "busy": busy, "idle": idle,
            "bubble_ratio": sum(idle) / (D * makespan), "peak_act": peak, "timeline": timeline}


# ---- closed forms (for comparison) ------------------------------------------------------------------

def bubble_formula(name: str, p: int, m: int, t: Times = Times(), v: int = 1) -> float:
    """Idle time per device predicted by the published formulas (see the module docstring)."""
    if name in ("gpipe", "1f1b"):
        return (p - 1) * (t.F + t.B_full)
    if name == "interleaved":
        return (p - 1) * (t.F + t.B_full) / v
    if name == "zb1p":                                   # DeepSeek-V3 Table 2 / DualPipe README
        return (p - 1) * (t.F + t.B_full - 2 * t.W)
    if name in ("dualpipe", "dualpipev"):                # p = number of stages PP
        fb = t.fb if t.fb is not None else t.F + t.B_full
        return (p / 2 - 1) * (fb + t.B_full - 3 * t.W)
    raise KeyError(name)


def bubble_ratio_formula(p: int, m: int, v: int = 1) -> float:
    """Idle fraction of 1F1B / GPipe ((p-1)/(m+p-1)) and of interleaved 1F1B ((p-1)/(v·m + p-1)) at F,B fixed."""
    return (p - 1) / (v * m + p - 1)


def gantt(result: dict, width: int = 100) -> str:
    """ASCII timeline: one row per device; F forward, B backward, b input-grad only, W weight grad, X overlapped."""
    T = result["makespan"]
    sym = {"F": "F", "B": "B", "Bz": "b", "W": "W", "FB": "X"}
    rows = []
    for d, tl in enumerate(result["timeline"]):
        line = [" "] * width
        for kind, f, b, s, e in tl:
            a, z = int(s / T * width), max(int(s / T * width) + 1, int(e / T * width))
            for i in range(a, min(z, width)):
                line[i] = sym[kind]
        rows.append(f"dev{d:<2d}|" + "".join(line) + "|")
    return "\n".join(rows)


def compare(p: int, m: int, t: Times = Times(), v: int = 2) -> list[dict]:
    """Simulate the standard schedules for ``p`` pipeline stages and ``m`` micro-batches.

    DualPipe runs on ``p`` devices (two stages each, 2× parameters); DualPipeV on ``p/2`` devices holding the
    same ``p`` stages, as in the DualPipe README's table.
    """
    rows = []
    cases = [("gpipe", gpipe(p, m), None), ("1f1b", one_f_one_b(p, m), None)]
    if m % p == 0:
        cases.append(("interleaved", interleaved(p, v, m), v))
    cases.append(("zb1p", zb1p(p, m), None))
    if p % 2 == 0 and m % 2 == 0 and m >= 2 * p:
        cases.append(("dualpipe", dualpipe(p, m), None))
    if p % 2 == 0 and m >= p:
        cases.append(("dualpipev", dualpipev(p // 2, m), None))
    for name, sch, vv in cases:
        r = simulate(sch, t)
        r["formula_idle"] = bubble_formula(name, p, m, t, vv or 1)
        r["key"] = name
        rows.append(r)
    return rows


__all__ = ["Op", "Schedule", "Times", "bubble_formula", "bubble_ratio_formula", "compare", "dualpipe",
           "dualpipev", "gantt", "gpipe", "interleaved", "one_f_one_b", "one_f_one_b_order", "simulate", "zb1p"]
